flowchart TD
    start(["メッセージを送信"]) --> validate["入力を検証"]
    validate --> valid{"有効なリクエストですか？"}

    valid -- "いいえ" --> inputError["入力エラーを表示"]
    inputError --> idle(["待機"])

    valid -- "はい" --> build["リクエストを作成<br>会話履歴 · モデル設定"]
    build --> gateway["AiGateway を呼び出す"]
    gateway --> stream["応答チャンクを受信"]

    stream --> more{"応答チャンクはまだありますか？"}
    more -- "はい" --> stream
    more -- "いいえ" --> save["応答を保存して UI を更新"]
    save --> idle

    gateway -- "呼び出し失敗" --> failure["エラーを表示して再試行"]
    failure --> idle
```
