    この Kotlin の例では、小規模なアプリケーション構造を示します：

```kotlin
data class Expense(
    val id: Long,
    val title: String,
    val category: String,
    val amount: Double,
    val createdAt: Long = System.currentTimeMillis()
)

class ExpenseRepository {
    private val expenses = mutableListOf<Expense>()

    fun add(expense: Expense) {
        expenses += expense
    }

    fun remove(id: Long) {
        expenses.removeAll { it.id == id }
    }

    fun observeAll(): List<Expense> = expenses.toList()

    fun total(): Double = expenses.sumOf { it.amount }

    fun totalByCategory(category: String): Double =
        expenses.filter { it.category == category }.sumOf { it.amount }
}

fun printSummary(repository: ExpenseRepository) {
    repository.observeAll()
        .groupBy { it.category }
        .forEach { (category, items) ->
            val total = items.sumOf { it.amount }
            println("$category: $total")
        }
}

fun main() {
    val repository = ExpenseRepository()
    repository.add(Expense(1, "Lunch", "Food", 12.5))
    repository.add(Expense(2, "Bus", "Transport", 2.0))
    repository.add(Expense(3, "Coffee", "Food", 4.5))

    printSummary(repository)
    println("Total: ${repository.total()}")
}
```
