```csharp
public sealed record Expense(int Id, string Title, string Category, decimal Amount);

public sealed class ExpenseRepository
{
    private readonly List<Expense> expenses = new();

    public void Add(Expense expense) => expenses.Add(expense);
    public decimal Total() => expenses.Sum(item => item.Amount);
    public IReadOnlyList<Expense> ByCategory(string category) =>
        expenses.Where(item => item.Category == category).ToList();
}

var repository = new ExpenseRepository();
repository.Add(new Expense(1, "Lunch", "Food", 12.5m));
repository.Add(new Expense(2, "Coffee", "Food", 4.5m));
Console.WriteLine($"Food total: {repository.ByCategory("Food").Sum(item => item.Amount):F2}");
```
    これは SQL の例です。

```sql
SELECT name, category, amount
FROM expenses
WHERE amount > 10000
ORDER BY amount DESC;
```

より長い例を見るには、/sql-long を入力してください。
    JOIN と集計を使用した SQL の長い例です。

```sql
SELECT u.name, e.category, SUM(e.amount) AS total_amount
FROM users AS u
JOIN expenses AS e ON e.user_id = u.id
GROUP BY u.name, e.category
ORDER BY total_amount DESC;
```

詳しい例を見るには、/sql-very-long を入力してください。
    サブクエリ、JOIN、集計を使用したネストされた SQL クエリの例です。

```sql
SELECT u.name, summary.category, summary.total_amount
FROM users AS u
JOIN (
    SELECT user_id, category, SUM(amount) AS total_amount
    FROM expenses
    WHERE amount > (
        SELECT AVG(amount) FROM expenses
    )
    GROUP BY user_id, category
) AS summary ON summary.user_id = u.id
WHERE summary.total_amount > 10000
ORDER BY summary.total_amount DESC;
```
    これは JavaScript の例です。

```javascript
const name = "SmartSpend";
const amount = 12500;
console.log(`${name}: ${amount} KRW`);
```

より長い例を見るには、/javascript-long を入力してください。
    これは JavaScript の長い例です。

```javascript
const expenses = [
    { title: "Lunch", category: "Food", amount: 12.5 },
    { title: "Bus", category: "Transport", amount: 2.0 }
];

const total = expenses.reduce((sum, expense) => sum + expense.amount, 0);
console.log(`Total: ${total.toFixed(2)}`);
```

詳しい例を見るには、/javascript-very-long を入力してください。
    この JavaScript の例では、非同期データ処理を示します。

```javascript
class ExpenseRepository {
    constructor() {
    this.expenses = [];
    }

    add(expense) {
    this.expenses.push(expense);
    }

    async summary() {
    return this.expenses.reduce((result, expense) => {
        result[expense.category] = (result[expense.category] || 0) + expense.amount;
        return result;
    }, {});
    }
}

const repository = new ExpenseRepository();
repository.add({ title: "Lunch", category: "Food", amount: 12.5 });
repository.add({ title: "Bus", category: "Transport", amount: 2.0 });
console.log(await repository.summary());
```
